def comps(g):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for i in range(h):
  for j in range(w):
   if g[i][j]==7 or (i,j) in seen: continue
   q=[(i,j)]; seen.add((i,j)); cc=[]
   while q:
    x,y=q.pop(); cc.append((x,y))
